//! 🗺️ Private backend conversion keeps all external types inside their real provider.
use super::*;
pub(super) fn texture_format(value:TextureFormat)->wgpu::TextureFormat{match value{TextureFormat::Rgba8Unorm=>wgpu::TextureFormat::Rgba8Unorm,TextureFormat::Rgba8UnormSrgb=>wgpu::TextureFormat::Rgba8UnormSrgb,TextureFormat::Bgra8Unorm=>wgpu::TextureFormat::Bgra8Unorm,TextureFormat::Bgra8UnormSrgb=>wgpu::TextureFormat::Bgra8UnormSrgb,TextureFormat::R8Unorm=>wgpu::TextureFormat::R8Unorm,TextureFormat::Depth24PlusStencil8=>wgpu::TextureFormat::Depth24PlusStencil8,TextureFormat::Depth32Float=>wgpu::TextureFormat::Depth32Float}}
pub(super) fn texture_dimension(value:TextureDimension)->wgpu::TextureDimension{match value{TextureDimension::D2=>wgpu::TextureDimension::D2}}
pub(super) fn texture_view_dimension(value:TextureViewDimension)->wgpu::TextureViewDimension{match value{TextureViewDimension::D2=>wgpu::TextureViewDimension::D2}}
pub(super) fn texture_aspect(value:TextureAspect)->wgpu::TextureAspect{match value{TextureAspect::All=>wgpu::TextureAspect::All}}
pub(super) fn compare_function(value:CompareFunction)->wgpu::CompareFunction{match value{CompareFunction::Always=>wgpu::CompareFunction::Always,CompareFunction::Equal=>wgpu::CompareFunction::Equal,CompareFunction::Less=>wgpu::CompareFunction::Less,CompareFunction::LessEqual=>wgpu::CompareFunction::LessEqual}}
pub(super) fn stencil_operation(value:StencilOperation)->wgpu::StencilOperation{match value{StencilOperation::Keep=>wgpu::StencilOperation::Keep,StencilOperation::Invert=>wgpu::StencilOperation::Invert,StencilOperation::Replace=>wgpu::StencilOperation::Replace}}
pub(super) fn face(value:Face)->wgpu::Face{match value{Face::Back=>wgpu::Face::Back}}
pub(super) fn primitive_topology(value:PrimitiveTopology)->wgpu::PrimitiveTopology{match value{PrimitiveTopology::TriangleList=>wgpu::PrimitiveTopology::TriangleList,PrimitiveTopology::LineList=>wgpu::PrimitiveTopology::LineList}}
pub(super) fn filter_mode(value:FilterMode)->wgpu::FilterMode{match value{FilterMode::Nearest=>wgpu::FilterMode::Nearest,FilterMode::Linear=>wgpu::FilterMode::Linear}}
pub(super) fn mipmap_filter_mode(value:MipmapFilterMode)->wgpu::MipmapFilterMode{match value{MipmapFilterMode::Nearest=>wgpu::MipmapFilterMode::Nearest,MipmapFilterMode::Linear=>wgpu::MipmapFilterMode::Linear}}
pub(super) fn address_mode(value:AddressMode)->wgpu::AddressMode{match value{AddressMode::ClampToEdge=>wgpu::AddressMode::ClampToEdge,AddressMode::MirrorRepeat=>wgpu::AddressMode::MirrorRepeat,AddressMode::Repeat=>wgpu::AddressMode::Repeat}}
pub(super) fn sampler_binding_type(value:SamplerBindingType)->wgpu::SamplerBindingType{match value{SamplerBindingType::Filtering=>wgpu::SamplerBindingType::Filtering,SamplerBindingType::Comparison=>wgpu::SamplerBindingType::Comparison}}
pub(super) fn buffer_binding_type(value:BufferBindingType)->wgpu::BufferBindingType{match value{BufferBindingType::Uniform=>wgpu::BufferBindingType::Uniform}}
pub(super) fn vertex_format(value:VertexFormat)->wgpu::VertexFormat{match value{VertexFormat::Float32x2=>wgpu::VertexFormat::Float32x2,VertexFormat::Float32x3=>wgpu::VertexFormat::Float32x3,VertexFormat::Float32x4=>wgpu::VertexFormat::Float32x4}}
pub(super) fn vertex_step_mode(value:VertexStepMode)->wgpu::VertexStepMode{match value{VertexStepMode::Vertex=>wgpu::VertexStepMode::Vertex,VertexStepMode::Instance=>wgpu::VertexStepMode::Instance}}
pub(super) fn index_format(value:IndexFormat)->wgpu::IndexFormat{match value{IndexFormat::Uint32=>wgpu::IndexFormat::Uint32}}
pub(super) fn store_op(value:StoreOp)->wgpu::StoreOp{match value{StoreOp::Store=>wgpu::StoreOp::Store}}
pub(super) fn map_mode(value:MapMode)->wgpu::MapMode{match value{MapMode::Read=>wgpu::MapMode::Read}}
pub(super) fn poll_type(value:PollType)->wgpu::PollType{match value{PollType::Poll=>wgpu::PollType::Poll}}
pub(super) fn present_mode(value:PresentMode)->wgpu::PresentMode{match value{PresentMode::AutoVsync=>wgpu::PresentMode::AutoVsync}}
pub(super) fn composite_alpha_mode(value:CompositeAlphaMode)->wgpu::CompositeAlphaMode{match value{CompositeAlphaMode::PreMultiplied=>wgpu::CompositeAlphaMode::PreMultiplied,CompositeAlphaMode::Auto=>wgpu::CompositeAlphaMode::Auto,CompositeAlphaMode::Opaque=>wgpu::CompositeAlphaMode::Opaque,CompositeAlphaMode::PostMultiplied=>wgpu::CompositeAlphaMode::PostMultiplied,CompositeAlphaMode::Inherit=>wgpu::CompositeAlphaMode::Inherit}}
pub(super) fn buffer_usages(value:BufferUsages)->wgpu::BufferUsages{let mut result=wgpu::BufferUsages::empty();if value.0&1!=0{result|=wgpu::BufferUsages::COPY_DST;}if value.0&2!=0{result|=wgpu::BufferUsages::INDEX;}if value.0&4!=0{result|=wgpu::BufferUsages::MAP_READ;}if value.0&8!=0{result|=wgpu::BufferUsages::STORAGE;}if value.0&16!=0{result|=wgpu::BufferUsages::UNIFORM;}if value.0&32!=0{result|=wgpu::BufferUsages::VERTEX;}result}
pub(super) fn texture_usages(value:TextureUsages)->wgpu::TextureUsages{let mut result=wgpu::TextureUsages::empty();if value.0&1!=0{result|=wgpu::TextureUsages::COPY_DST;}if value.0&2!=0{result|=wgpu::TextureUsages::COPY_SRC;}if value.0&4!=0{result|=wgpu::TextureUsages::RENDER_ATTACHMENT;}if value.0&8!=0{result|=wgpu::TextureUsages::STORAGE_BINDING;}if value.0&16!=0{result|=wgpu::TextureUsages::TEXTURE_BINDING;}result}
pub(super) fn shader_stages(value:ShaderStages)->wgpu::ShaderStages{let mut result=wgpu::ShaderStages::empty();if value.0&1!=0{result|=wgpu::ShaderStages::VERTEX;}if value.0&2!=0{result|=wgpu::ShaderStages::FRAGMENT;}result}
pub(super) fn color_writes(value:ColorWrites)->wgpu::ColorWrites{let mut result=wgpu::ColorWrites::empty();if value.0&1!=0{result|=wgpu::ColorWrites::ALL;}result}

pub(super) fn format(value:wgpu::TextureFormat)->Option<TextureFormat>{match value{wgpu::TextureFormat::Rgba8Unorm=>Some(TextureFormat::Rgba8Unorm),wgpu::TextureFormat::Rgba8UnormSrgb=>Some(TextureFormat::Rgba8UnormSrgb),wgpu::TextureFormat::Bgra8Unorm=>Some(TextureFormat::Bgra8Unorm),wgpu::TextureFormat::Bgra8UnormSrgb=>Some(TextureFormat::Bgra8UnormSrgb),wgpu::TextureFormat::R8Unorm=>Some(TextureFormat::R8Unorm),wgpu::TextureFormat::Depth24PlusStencil8=>Some(TextureFormat::Depth24PlusStencil8),wgpu::TextureFormat::Depth32Float=>Some(TextureFormat::Depth32Float),_=>None}}
pub(super) fn extent(value:Extent3d)->wgpu::Extent3d{wgpu::Extent3d{width:value.width,height:value.height,depth_or_array_layers:value.depth_or_array_layers}}
pub(super) fn origin(value:Origin3d)->wgpu::Origin3d{wgpu::Origin3d{x:value.x,y:value.y,z:value.z}}
pub(super) fn color(value:Color)->wgpu::Color{wgpu::Color{r:value.r,g:value.g,b:value.b,a:value.a}}
pub(super) fn blend_state(value:BlendState)->wgpu::BlendState{match value{BlendState::Alpha=>wgpu::BlendState::ALPHA_BLENDING,BlendState::Replace=>wgpu::BlendState::REPLACE}}
pub(super) fn binding_type(value:BindingType)->wgpu::BindingType{match value{BindingType::Buffer{ty,has_dynamic_offset,min_binding_size}=>wgpu::BindingType::Buffer{ty:buffer_binding_type(ty),has_dynamic_offset,min_binding_size},BindingType::Sampler(ty)=>wgpu::BindingType::Sampler(sampler_binding_type(ty)),BindingType::Texture{sample_type,view_dimension,multisampled}=>wgpu::BindingType::Texture{sample_type:match sample_type{TextureSampleType::Float{filterable}=>wgpu::TextureSampleType::Float{filterable},TextureSampleType::Depth=>wgpu::TextureSampleType::Depth},view_dimension:texture_view_dimension(view_dimension),multisampled}}}
fn stencil_face(value:StencilFaceState)->wgpu::StencilFaceState{wgpu::StencilFaceState{compare:compare_function(value.compare),fail_op:stencil_operation(value.fail_op),depth_fail_op:stencil_operation(value.depth_fail_op),pass_op:stencil_operation(value.pass_op)}}
pub(super) fn depth(value:&DepthStencilState)->wgpu::DepthStencilState{wgpu::DepthStencilState{format:texture_format(value.format),depth_write_enabled:value.depth_write_enabled,depth_compare:value.depth_compare.map(compare_function),stencil:wgpu::StencilState{front:stencil_face(value.stencil.front),back:stencil_face(value.stencil.back),read_mask:value.stencil.read_mask,write_mask:value.stencil.write_mask},bias:wgpu::DepthBiasState{constant:value.bias.constant,slope_scale:value.bias.slope_scale,clamp:value.bias.clamp}}}
pub(super) fn operations<T,U>(value:Operations<T>,map:impl FnOnce(T)->U)->wgpu::Operations<U>{wgpu::Operations{load:match value.load{LoadOp::Load=>wgpu::LoadOp::Load,LoadOp::Clear(value)=>wgpu::LoadOp::Clear(map(value))},store:store_op(value.store)}}
pub(super) fn texture_copy(value:TexelCopyTextureInfo<'_>)->wgpu::TexelCopyTextureInfo<'_>{wgpu::TexelCopyTextureInfo{texture:&value.texture.raw,mip_level:value.mip_level,origin:origin(value.origin),aspect:texture_aspect(value.aspect)}}
pub(super) fn copy_layout(value:TexelCopyBufferLayout)->wgpu::TexelCopyBufferLayout{wgpu::TexelCopyBufferLayout{offset:value.offset,bytes_per_row:value.bytes_per_row,rows_per_image:value.rows_per_image}}
pub(super) fn surface_config(value:&SurfaceConfiguration)->wgpu::SurfaceConfiguration{wgpu::SurfaceConfiguration{usage:texture_usages(value.usage),format:texture_format(value.format),width:value.width,height:value.height,present_mode:present_mode(value.present_mode),alpha_mode:composite_alpha_mode(value.alpha_mode),view_formats:value.view_formats.iter().copied().map(texture_format).collect(),desired_maximum_frame_latency:value.desired_maximum_frame_latency}}
